"""Dependency-free, offline research dashboard for engine output.

The browser selects precomputed results and plots them. It never calibrates a
model, fetches a price, or runs a hedge simulation.
"""

from __future__ import annotations

import json
from pathlib import Path


def write_report(result: dict, path: Path) -> None:
    """Write a self-contained dashboard, rejecting non-finite JSON values.

    Escaping ``<`` keeps source data from terminating the inert JSON script
    element. All dynamic labels in the page are separately HTML-escaped.
    """
    payload = json.dumps(result, ensure_ascii=False, allow_nan=False)
    payload = payload.replace("<", "\\u003c").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    destination = Path(path)
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(_HTML.replace("__DATA_JSON__", payload, 1), encoding="utf-8")


